CREATE OR REPLACE FUNCTION public.admin_set_voucher_used(p_reward uuid, p_used boolean)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
